('rev-1649089647329878634-1', '1649089647329878634', 'Trịnh Quang Huy', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=150&q=80', 5, 'Trải nghiệm nghỉ dưỡng tuyệt vời! Nhà tắm sạch bóng, nước nóng mạnh, máy lạnh mát rượi. Đánh giá 5 sao cho chất lượng dịch vụ của chủ nhà.', 'Rất cảm ơn bạn đã góp ý quý báu. Chúc bạn nhiều sức khỏe và hy vọng lại được gặp bạn trong chuyến du lịch tiếp theo!', '05/09/2026'),
('rev-1649089647329878634-2', '1649089647329878634', 'Nguyễn Hoàng Nam', 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=150&q=80', 5, 'Chủ nhà vô cùng nhiệt tình và chu đáo, hướng dẫn check-in chi tiết và phản hồi rất nhanh. Không gian yên tĩnh, giường êm giúp mình có giấc ngủ ngon sau ngày dài dạo chơi.', 'Cảm ơn những lời nhận xét chân thành của bạn. Sự hài lòng của quý khách là động lực lớn nhất của chúng mình. Chúc bạn luôn có những chuyến đi thật vui vẻ!', '11/08/2026'),
('rev-1649089647329878634-3', '1649089647329878634', 'Hoàng Kim Ngân', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=150&q=80', 5, 'Phòng ốc y hệt như hình ảnh đăng tải. Thiết kế tinh tế, không gian thoáng đãng. Rất phù hợp cho cặp đôi hoặc người đi công tác cần không gian làm việc riêng.', NULL, '11/08/2026'),
('rev-1439492530995166642-1', '1439492530995166642', 'Nguyễn Hoàng Nam', 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=150&q=80', 4, 'Không gian đẹp, chủ nhà nhiệt tình. Căn phòng hơi cách âm chưa hoàn hảo nếu có xe cộ qua lại, bù lại view và tiện nghi rất xứng đáng với giá tiền.', NULL, '04/09/2026'),
('rev-1439492530995166642-2', '1439492530995166642', 'Đinh Ngọc Mai', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=150&q=80', 5, 'Phòng ốc y hệt như hình ảnh đăng tải. Thiết kế tinh tế, không gian thoáng đãng. Rất phù hợp cho cặp đôi hoặc người đi công tác cần không gian làm việc riêng.', NULL, '20/08/2026'),
('rev-1439492530995166642-3', '1439492530995166642', 'Đặng Thế Bảo', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=150&q=80', 5, 'Phòng ốc y hệt như hình ảnh đăng tải. Thiết kế tinh tế, không gian thoáng đãng. Rất phù hợp cho cặp đôi hoặc người đi công tác cần không gian làm việc riêng.', NULL, '01/08/2026'),
('rev-1439492530995166642-4', '1439492530995166642', 'Trần Thị Bích', 'https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=150&q=80', 5, 'Trải nghiệm nghỉ dưỡng tuyệt vời! Nhà tắm sạch bóng, nước nóng mạnh, máy lạnh mát rượi. Đánh giá 5 sao cho chất lượng dịch vụ của chủ nhà.', 'Cảm ơn những lời nhận xét chân thành của bạn. Sự hài lòng của quý khách là động lực lớn nhất của chúng mình. Chúc bạn luôn có những chuyến đi thật vui vẻ!', '05/07/2026'),
('rev-1759981772793424606-1', '1759981772793424606', 'Trịnh Quang Huy', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=150&q=80', 5, 'Góc ban công ngắm cảnh rất chill, ánh sáng tự nhiên ngập tràn phòng. Đồ dùng trong phòng đều mới và cao cấp. Chắc chắn sẽ quay lại khi có dịp!', 'Cảm ơn bạn rất nhiều vì đã lựa chọn nghỉ ngơi tại căn hộ của mình! Rất vui vì bạn đã có trải nghiệm đáng nhớ và hy vọng sớm được đón tiếp bạn lần tới nhé!', '17/09/2026'),
('rev-1759981772793424606-2', '1759981772793424606', 'Lương Tuấn Anh', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=150&q=80', 5, 'Góc ban công ngắm cảnh rất chill, ánh sáng tự nhiên ngập tràn phòng. Đồ dùng trong phòng đều mới và cao cấp. Chắc chắn sẽ quay lại khi có dịp!', 'Rất cảm ơn bạn đã góp ý quý báu. Chúc bạn nhiều sức khỏe và hy vọng lại được gặp bạn trong chuyến du lịch tiếp theo!', '22/08/2026'),
('rev-1759981772793424606-3', '1759981772793424606', 'Đinh Ngọc Mai', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=150&q=80', 5, 'Phòng ốc y hệt như hình ảnh đăng tải. Thiết kế tinh tế, không gian thoáng đãng. Rất phù hợp cho cặp đôi hoặc người đi công tác cần không gian làm việc riêng.', NULL, '01/08/2026')
INSERT INTO reviews (id, listing_id, reviewer_name, reviewer_avatar, rating, comment, host_reply, review_date) VALUES
('rev-1759981772793424606-4', '1759981772793424606', 'Vũ Thành Đạt', 'https://images.unsplash.com/photo-1570295999919-56ceb5ecca61?auto=format&fit=crop&w=150&q=80', 5, 'Vị trí đắc địa, xung quanh có rất nhiều quán cà phê đẹp và quán ăn ngon bản địa. Khóa thông minh tự nhận phòng cực kỳ tiện lợi và an toàn.', 'Cảm ơn bạn rất nhiều vì đã lựa chọn nghỉ ngơi tại căn hộ của mình! Rất vui vì bạn đã có trải nghiệm đáng nhớ và hy vọng sớm được đón tiếp bạn lần tới nhé!', '29/07/2026'),
