('rev-1627264490649725695-3', '1627264490649725695', 'Lương Tuấn Anh', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=150&q=80', 5, 'Căn hộ đẹp lung linh, sống ảo góc nào cũng xinh. Đồ đạc được sắp xếp gọn gàng, ngăn nắp. Rất thích sự hiếu khách và hỗ trợ tận tình của bạn host.', NULL, '30/07/2026'),
('rev-1627264490649725695-4', '1627264490649725695', 'Hoàng Kim Ngân', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=150&q=80', 5, 'Căn hộ đẹp lung linh, sống ảo góc nào cũng xinh. Đồ đạc được sắp xếp gọn gàng, ngăn nắp. Rất thích sự hiếu khách và hỗ trợ tận tình của bạn host.', NULL, '17/06/2026'),
('rev-1549895523979616266-1', '1549895523979616266', 'Phạm Thu Thảo', 'https://images.unsplash.com/photo-1567532939604-b6b5b0db2604?auto=format&fit=crop&w=150&q=80', 5, 'Phòng ốc y hệt như hình ảnh đăng tải. Thiết kế tinh tế, không gian thoáng đãng. Rất phù hợp cho cặp đôi hoặc người đi công tác cần không gian làm việc riêng.', NULL, '07/09/2026'),
('rev-1549895523979616266-2', '1549895523979616266', 'Bùi Phương Linh', 'https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=150&q=80', 5, 'Vị trí đắc địa, xung quanh có rất nhiều quán cà phê đẹp và quán ăn ngon bản địa. Khóa thông minh tự nhận phòng cực kỳ tiện lợi và an toàn.', NULL, '11/08/2026'),
('rev-1549895523979616266-3', '1549895523979616266', 'Đinh Ngọc Mai', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=150&q=80', 5, 'Căn hộ đẹp lung linh, sống ảo góc nào cũng xinh. Đồ đạc được sắp xếp gọn gàng, ngăn nắp. Rất thích sự hiếu khách và hỗ trợ tận tình của bạn host.', 'Rất cảm ơn bạn đã góp ý quý báu. Chúc bạn nhiều sức khỏe và hy vọng lại được gặp bạn trong chuyến du lịch tiếp theo!', '18/08/2026'),
('rev-1736115902862592916-1', '1736115902862592916', 'Lương Tuấn Anh', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=150&q=80', 5, 'Phòng ốc y hệt như hình ảnh đăng tải. Thiết kế tinh tế, không gian thoáng đãng. Rất phù hợp cho cặp đôi hoặc người đi công tác cần không gian làm việc riêng.', 'Cảm ơn bạn rất nhiều vì đã lựa chọn nghỉ ngơi tại căn hộ của mình! Rất vui vì bạn đã có trải nghiệm đáng nhớ và hy vọng sớm được đón tiếp bạn lần tới nhé!', '01/09/2026'),
('rev-1736115902862592916-2', '1736115902862592916', 'Đinh Ngọc Mai', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=150&q=80', 5, 'Căn phòng tuyệt vời vượt xa mong đợi của mình! Rất sạch sẽ, thơm tho và đầy đủ tiện nghi từ máy sấy, bàn là đến bếp nấu. Vị trí ngay trung tâm rất thuận tiện đi lại.', 'Rất cảm ơn bạn đã góp ý quý báu. Chúc bạn nhiều sức khỏe và hy vọng lại được gặp bạn trong chuyến du lịch tiếp theo!', '13/08/2026'),
('rev-1736115902862592916-3', '1736115902862592916', 'Cao Thùy Trang', 'https://images.unsplash.com/photo-1524504388940-b1c1722653e1?auto=format&fit=crop&w=150&q=80', 5, 'Căn phòng tuyệt vời vượt xa mong đợi của mình! Rất sạch sẽ, thơm tho và đầy đủ tiện nghi từ máy sấy, bàn là đến bếp nấu. Vị trí ngay trung tâm rất thuận tiện đi lại.', NULL, '16/07/2026')
INSERT INTO reviews (id, listing_id, reviewer_name, reviewer_avatar, rating, comment, host_reply, review_date) VALUES
('rev-1601075672794559363-1', '1601075672794559363', 'Cao Thùy Trang', 'https://images.unsplash.com/photo-1524504388940-b1c1722653e1?auto=format&fit=crop&w=150&q=80', 4, 'Không gian đẹp, chủ nhà nhiệt tình. Căn phòng hơi cách âm chưa hoàn hảo nếu có xe cộ qua lại, bù lại view và tiện nghi rất xứng đáng với giá tiền.', 'Cảm ơn những lời nhận xét chân thành của bạn. Sự hài lòng của quý khách là động lực lớn nhất của chúng mình. Chúc bạn luôn có những chuyến đi thật vui vẻ!', '15/09/2026'),
