('rev-1386671958159777398-4', '1386671958159777398', 'Đinh Ngọc Mai', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=150&q=80', 5, 'Góc ban công ngắm cảnh rất chill, ánh sáng tự nhiên ngập tràn phòng. Đồ dùng trong phòng đều mới và cao cấp. Chắc chắn sẽ quay lại khi có dịp!', NULL, '02/07/2026'),
('rev-1432492178950575248-1', '1432492178950575248', 'Lê Minh Trí', 'https://images.unsplash.com/photo-1628157582853-a796fa650a6a?auto=format&fit=crop&w=150&q=80', 5, 'Góc ban công ngắm cảnh rất chill, ánh sáng tự nhiên ngập tràn phòng. Đồ dùng trong phòng đều mới và cao cấp. Chắc chắn sẽ quay lại khi có dịp!', NULL, '01/09/2026'),
('rev-1432492178950575248-2', '1432492178950575248', 'Phạm Thu Thảo', 'https://images.unsplash.com/photo-1567532939604-b6b5b0db2604?auto=format&fit=crop&w=150&q=80', 5, 'Căn hộ đẹp lung linh, sống ảo góc nào cũng xinh. Đồ đạc được sắp xếp gọn gàng, ngăn nắp. Rất thích sự hiếu khách và hỗ trợ tận tình của bạn host.', 'Cảm ơn những lời nhận xét chân thành của bạn. Sự hài lòng của quý khách là động lực lớn nhất của chúng mình. Chúc bạn luôn có những chuyến đi thật vui vẻ!', '12/08/2026'),
('rev-1432492178950575248-3', '1432492178950575248', 'Nguyễn Hoàng Nam', 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=150&q=80', 5, 'Căn hộ đẹp lung linh, sống ảo góc nào cũng xinh. Đồ đạc được sắp xếp gọn gàng, ngăn nắp. Rất thích sự hiếu khách và hỗ trợ tận tình của bạn host.', NULL, '16/08/2026'),
('rev-1432492178950575248-4', '1432492178950575248', 'Đặng Thế Bảo', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=150&q=80', 5, 'Căn hộ đẹp lung linh, sống ảo góc nào cũng xinh. Đồ đạc được sắp xếp gọn gàng, ngăn nắp. Rất thích sự hiếu khách và hỗ trợ tận tình của bạn host.', 'Cảm ơn bạn rất nhiều vì đã lựa chọn nghỉ ngơi tại căn hộ của mình! Rất vui vì bạn đã có trải nghiệm đáng nhớ và hy vọng sớm được đón tiếp bạn lần tới nhé!', '15/07/2026'),
