('rev-1004728341544189623-4', '1004728341544189623', 'Đặng Thế Bảo', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=150&q=80', 5, 'Chủ nhà vô cùng nhiệt tình và chu đáo, hướng dẫn check-in chi tiết và phản hồi rất nhanh. Không gian yên tĩnh, giường êm giúp mình có giấc ngủ ngon sau ngày dài dạo chơi.', NULL, '02/08/2026'),
('rev-1004728341544189623-5', '1004728341544189623', 'Phạm Thu Thảo', 'https://images.unsplash.com/photo-1567532939604-b6b5b0db2604?auto=format&fit=crop&w=150&q=80', 5, 'Căn phòng tuyệt vời vượt xa mong đợi của mình! Rất sạch sẽ, thơm tho và đầy đủ tiện nghi từ máy sấy, bàn là đến bếp nấu. Vị trí ngay trung tâm rất thuận tiện đi lại.', 'Cảm ơn những lời nhận xét chân thành của bạn. Sự hài lòng của quý khách là động lực lớn nhất của chúng mình. Chúc bạn luôn có những chuyến đi thật vui vẻ!', '06/06/2026'),
('rev-1478031486477629804-1', '1478031486477629804', 'Nguyễn Hoàng Nam', 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=150&q=80', 5, 'Căn phòng tuyệt vời vượt xa mong đợi của mình! Rất sạch sẽ, thơm tho và đầy đủ tiện nghi từ máy sấy, bàn là đến bếp nấu. Vị trí ngay trung tâm rất thuận tiện đi lại.', NULL, '17/09/2026'),
('rev-1478031486477629804-2', '1478031486477629804', 'Trịnh Quang Huy', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=150&q=80', 4, 'Phòng sạch sẽ và tiện nghi ổn, vị trí thuận lợi. Điểm trừ nhỏ là giờ cao điểm đường hơi đông một chút, nhưng nhìn chung kỳ nghỉ rất thoải mái.', 'Cảm ơn bạn rất nhiều vì đã lựa chọn nghỉ ngơi tại căn hộ của mình! Rất vui vì bạn đã có trải nghiệm đáng nhớ và hy vọng sớm được đón tiếp bạn lần tới nhé!', '13/08/2026'),
('rev-1478031486477629804-3', '1478031486477629804', 'Trần Thị Bích', 'https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=150&q=80', 5, 'Trải nghiệm nghỉ dưỡng tuyệt vời! Nhà tắm sạch bóng, nước nóng mạnh, máy lạnh mát rượi. Đánh giá 5 sao cho chất lượng dịch vụ của chủ nhà.', 'Cảm ơn bạn rất nhiều vì đã lựa chọn nghỉ ngơi tại căn hộ của mình! Rất vui vì bạn đã có trải nghiệm đáng nhớ và hy vọng sớm được đón tiếp bạn lần tới nhé!', '01/08/2026'),
('rev-1478031486477629804-4', '1478031486477629804', 'Đinh Ngọc Mai', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=150&q=80', 5, 'Căn hộ đẹp lung linh, sống ảo góc nào cũng xinh. Đồ đạc được sắp xếp gọn gàng, ngăn nắp. Rất thích sự hiếu khách và hỗ trợ tận tình của bạn host.', 'Rất cảm ơn bạn đã góp ý quý báu. Chúc bạn nhiều sức khỏe và hy vọng lại được gặp bạn trong chuyến du lịch tiếp theo!', '28/07/2026')
INSERT INTO reviews (id, listing_id, reviewer_name, reviewer_avatar, rating, comment, host_reply, review_date) VALUES
('rev-1478031486477629804-5', '1478031486477629804', 'Bùi Phương Linh', 'https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=150&q=80', 5, 'Vị trí đắc địa, xung quanh có rất nhiều quán cà phê đẹp và quán ăn ngon bản địa. Khóa thông minh tự nhận phòng cực kỳ tiện lợi và an toàn.', NULL, '14/07/2026'),
('rev-1663083542125523465-1', '1663083542125523465', 'Lương Tuấn Anh', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=150&q=80', 5, 'Góc ban công ngắm cảnh rất chill, ánh sáng tự nhiên ngập tràn phòng. Đồ dùng trong phòng đều mới và cao cấp. Chắc chắn sẽ quay lại khi có dịp!', 'Cảm ơn những lời nhận xét chân thành của bạn. Sự hài lòng của quý khách là động lực lớn nhất của chúng mình. Chúc bạn luôn có những chuyến đi thật vui vẻ!', '16/09/2026'),
('rev-1663083542125523465-2', '1663083542125523465', 'Hoàng Kim Ngân', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=150&q=80', 5, 'Chủ nhà vô cùng nhiệt tình và chu đáo, hướng dẫn check-in chi tiết và phản hồi rất nhanh. Không gian yên tĩnh, giường êm giúp mình có giấc ngủ ngon sau ngày dài dạo chơi.', 'Cảm ơn những lời nhận xét chân thành của bạn. Sự hài lòng của quý khách là động lực lớn nhất của chúng mình. Chúc bạn luôn có những chuyến đi thật vui vẻ!', '29/08/2026'),
('rev-1663083542125523465-3', '1663083542125523465', 'Bùi Phương Linh', 'https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=150&q=80', 5, 'Trải nghiệm nghỉ dưỡng tuyệt vời! Nhà tắm sạch bóng, nước nóng mạnh, máy lạnh mát rượi. Đánh giá 5 sao cho chất lượng dịch vụ của chủ nhà.', 'Rất cảm ơn bạn đã góp ý quý báu. Chúc bạn nhiều sức khỏe và hy vọng lại được gặp bạn trong chuyến du lịch tiếp theo!', '25/07/2026'),
