('rev-1555764203632285524-3', '1555764203632285524', 'Bùi Phương Linh', 'https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=150&q=80', 5, 'Phòng ốc y hệt như hình ảnh đăng tải. Thiết kế tinh tế, không gian thoáng đãng. Rất phù hợp cho cặp đôi hoặc người đi công tác cần không gian làm việc riêng.', 'Cảm ơn bạn rất nhiều vì đã lựa chọn nghỉ ngơi tại căn hộ của mình! Rất vui vì bạn đã có trải nghiệm đáng nhớ và hy vọng sớm được đón tiếp bạn lần tới nhé!', '16/07/2026')
INSERT INTO reviews (id, listing_id, reviewer_name, reviewer_avatar, rating, comment, host_reply, review_date) VALUES
('rev-1555764203632285524-4', '1555764203632285524', 'Nguyễn Hoàng Nam', 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=150&q=80', 5, 'Trải nghiệm nghỉ dưỡng tuyệt vời! Nhà tắm sạch bóng, nước nóng mạnh, máy lạnh mát rượi. Đánh giá 5 sao cho chất lượng dịch vụ của chủ nhà.', 'Cảm ơn bạn rất nhiều vì đã lựa chọn nghỉ ngơi tại căn hộ của mình! Rất vui vì bạn đã có trải nghiệm đáng nhớ và hy vọng sớm được đón tiếp bạn lần tới nhé!', '30/06/2026'),
('rev-699635193295533212-1', '699635193295533212', 'Nguyễn Hoàng Nam', 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=150&q=80', 5, 'Vị trí đắc địa, xung quanh có rất nhiều quán cà phê đẹp và quán ăn ngon bản địa. Khóa thông minh tự nhận phòng cực kỳ tiện lợi và an toàn.', 'Cảm ơn những lời nhận xét chân thành của bạn. Sự hài lòng của quý khách là động lực lớn nhất của chúng mình. Chúc bạn luôn có những chuyến đi thật vui vẻ!', '01/09/2026'),
('rev-699635193295533212-2', '699635193295533212', 'Bùi Phương Linh', 'https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=150&q=80', 5, 'Trải nghiệm nghỉ dưỡng tuyệt vời! Nhà tắm sạch bóng, nước nóng mạnh, máy lạnh mát rượi. Đánh giá 5 sao cho chất lượng dịch vụ của chủ nhà.', NULL, '24/08/2026'),
('rev-699635193295533212-3', '699635193295533212', 'Trần Thị Bích', 'https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=150&q=80', 5, 'Trải nghiệm nghỉ dưỡng tuyệt vời! Nhà tắm sạch bóng, nước nóng mạnh, máy lạnh mát rượi. Đánh giá 5 sao cho chất lượng dịch vụ của chủ nhà.', 'Cảm ơn những lời nhận xét chân thành của bạn. Sự hài lòng của quý khách là động lực lớn nhất của chúng mình. Chúc bạn luôn có những chuyến đi thật vui vẻ!', '03/08/2026'),
('rev-1188048155349315217-1', '1188048155349315217', 'Trần Thị Bích', 'https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=150&q=80', 5, 'Trải nghiệm nghỉ dưỡng tuyệt vời! Nhà tắm sạch bóng, nước nóng mạnh, máy lạnh mát rượi. Đánh giá 5 sao cho chất lượng dịch vụ của chủ nhà.', NULL, '04/09/2026'),
('rev-1188048155349315217-2', '1188048155349315217', 'Lương Tuấn Anh', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=150&q=80', 4, 'Phòng sạch sẽ và tiện nghi ổn, vị trí thuận lợi. Điểm trừ nhỏ là giờ cao điểm đường hơi đông một chút, nhưng nhìn chung kỳ nghỉ rất thoải mái.', NULL, '14/08/2026'),
('rev-1188048155349315217-3', '1188048155349315217', 'Bùi Phương Linh', 'https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=150&q=80', 5, 'Phòng ốc y hệt như hình ảnh đăng tải. Thiết kế tinh tế, không gian thoáng đãng. Rất phù hợp cho cặp đôi hoặc người đi công tác cần không gian làm việc riêng.', NULL, '24/07/2026'),
('rev-1552807577235754752-1', '1552807577235754752', 'Hoàng Kim Ngân', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=150&q=80', 4, 'Không gian đẹp, chủ nhà nhiệt tình. Căn phòng hơi cách âm chưa hoàn hảo nếu có xe cộ qua lại, bù lại view và tiện nghi rất xứng đáng với giá tiền.', 'Cảm ơn những lời nhận xét chân thành của bạn. Sự hài lòng của quý khách là động lực lớn nhất của chúng mình. Chúc bạn luôn có những chuyến đi thật vui vẻ!', '09/09/2026'),
('rev-1552807577235754752-2', '1552807577235754752', 'Đặng Thế Bảo', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=150&q=80', 5, 'Vị trí đắc địa, xung quanh có rất nhiều quán cà phê đẹp và quán ăn ngon bản địa. Khóa thông minh tự nhận phòng cực kỳ tiện lợi và an toàn.', 'Cảm ơn những lời nhận xét chân thành của bạn. Sự hài lòng của quý khách là động lực lớn nhất của chúng mình. Chúc bạn luôn có những chuyến đi thật vui vẻ!', '31/08/2026'),
('rev-1552807577235754752-3', '1552807577235754752', 'Phạm Thu Thảo', 'https://images.unsplash.com/photo-1567532939604-b6b5b0db2604?auto=format&fit=crop&w=150&q=80', 4, 'Phòng sạch sẽ và tiện nghi ổn, vị trí thuận lợi. Điểm trừ nhỏ là giờ cao điểm đường hơi đông một chút, nhưng nhìn chung kỳ nghỉ rất thoải mái.', 'Cảm ơn những lời nhận xét chân thành của bạn. Sự hài lòng của quý khách là động lực lớn nhất của chúng mình. Chúc bạn luôn có những chuyến đi thật vui vẻ!', '31/07/2026'),
('rev-1552807577235754752-4', '1552807577235754752', 'Trần Thị Bích', 'https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=150&q=80', 5, 'Góc ban công ngắm cảnh rất chill, ánh sáng tự nhiên ngập tràn phòng. Đồ dùng trong phòng đều mới và cao cấp. Chắc chắn sẽ quay lại khi có dịp!', NULL, '18/06/2026'),
('rev-1716019892785427480-1', '1716019892785427480', 'Đặng Thế Bảo', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=150&q=80', 5, 'Góc ban công ngắm cảnh rất chill, ánh sáng tự nhiên ngập tràn phòng. Đồ dùng trong phòng đều mới và cao cấp. Chắc chắn sẽ quay lại khi có dịp!', 'Rất cảm ơn bạn đã góp ý quý báu. Chúc bạn nhiều sức khỏe và hy vọng lại được gặp bạn trong chuyến du lịch tiếp theo!', '14/09/2026'),
('rev-1716019892785427480-2', '1716019892785427480', 'Vũ Thành Đạt', 'https://images.unsplash.com/photo-1570295999919-56ceb5ecca61?auto=format&fit=crop&w=150&q=80', 5, 'Chủ nhà vô cùng nhiệt tình và chu đáo, hướng dẫn check-in chi tiết và phản hồi rất nhanh. Không gian yên tĩnh, giường êm giúp mình có giấc ngủ ngon sau ngày dài dạo chơi.', 'Cảm ơn những lời nhận xét chân thành của bạn. Sự hài lòng của quý khách là động lực lớn nhất của chúng mình. Chúc bạn luôn có những chuyến đi thật vui vẻ!', '31/08/2026'),
('rev-1716019892785427480-3', '1716019892785427480', 'Lương Tuấn Anh', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=150&q=80', 5, 'Chủ nhà vô cùng nhiệt tình và chu đáo, hướng dẫn check-in chi tiết và phản hồi rất nhanh. Không gian yên tĩnh, giường êm giúp mình có giấc ngủ ngon sau ngày dài dạo chơi.', 'Cảm ơn những lời nhận xét chân thành của bạn. Sự hài lòng của quý khách là động lực lớn nhất của chúng mình. Chúc bạn luôn có những chuyến đi thật vui vẻ!', '12/07/2026'),
('rev-1489168370074552950-1', '1489168370074552950', 'Đặng Thế Bảo', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=150&q=80', 5, 'Căn hộ đẹp lung linh, sống ảo góc nào cũng xinh. Đồ đạc được sắp xếp gọn gàng, ngăn nắp. Rất thích sự hiếu khách và hỗ trợ tận tình của bạn host.', 'Cảm ơn những lời nhận xét chân thành của bạn. Sự hài lòng của quý khách là động lực lớn nhất của chúng mình. Chúc bạn luôn có những chuyến đi thật vui vẻ!', '08/09/2026'),
