('rev-21370079-1', '21370079', 'Đặng Thế Bảo', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=150&q=80', 4, 'Không gian đẹp, chủ nhà nhiệt tình. Căn phòng hơi cách âm chưa hoàn hảo nếu có xe cộ qua lại, bù lại view và tiện nghi rất xứng đáng với giá tiền.', NULL, '31/08/2026'),
('rev-21370079-2', '21370079', 'Trịnh Quang Huy', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=150&q=80', 5, 'Căn hộ đẹp lung linh, sống ảo góc nào cũng xinh. Đồ đạc được sắp xếp gọn gàng, ngăn nắp. Rất thích sự hiếu khách và hỗ trợ tận tình của bạn host.', NULL, '27/08/2026'),
('rev-21370079-3', '21370079', 'Lê Minh Trí', 'https://images.unsplash.com/photo-1628157582853-a796fa650a6a?auto=format&fit=crop&w=150&q=80', 5, 'Góc ban công ngắm cảnh rất chill, ánh sáng tự nhiên ngập tràn phòng. Đồ dùng trong phòng đều mới và cao cấp. Chắc chắn sẽ quay lại khi có dịp!', 'Cảm ơn những lời nhận xét chân thành của bạn. Sự hài lòng của quý khách là động lực lớn nhất của chúng mình. Chúc bạn luôn có những chuyến đi thật vui vẻ!', '22/07/2026'),
('rev-21370079-4', '21370079', 'Trần Thị Bích', 'https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=150&q=80', 5, 'Trải nghiệm nghỉ dưỡng tuyệt vời! Nhà tắm sạch bóng, nước nóng mạnh, máy lạnh mát rượi. Đánh giá 5 sao cho chất lượng dịch vụ của chủ nhà.', NULL, '18/07/2026'),
('rev-21370079-5', '21370079', 'Vũ Thành Đạt', 'https://images.unsplash.com/photo-1570295999919-56ceb5ecca61?auto=format&fit=crop&w=150&q=80', 5, 'Căn phòng tuyệt vời vượt xa mong đợi của mình! Rất sạch sẽ, thơm tho và đầy đủ tiện nghi từ máy sấy, bàn là đến bếp nấu. Vị trí ngay trung tâm rất thuận tiện đi lại.', NULL, '15/07/2026'),
('rev-1030685776933399138-1', '1030685776933399138', 'Đinh Ngọc Mai', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=150&q=80', 5, 'Căn hộ đẹp lung linh, sống ảo góc nào cũng xinh. Đồ đạc được sắp xếp gọn gàng, ngăn nắp. Rất thích sự hiếu khách và hỗ trợ tận tình của bạn host.', 'Cảm ơn bạn rất nhiều vì đã lựa chọn nghỉ ngơi tại căn hộ của mình! Rất vui vì bạn đã có trải nghiệm đáng nhớ và hy vọng sớm được đón tiếp bạn lần tới nhé!', '11/09/2026'),
('rev-1030685776933399138-2', '1030685776933399138', 'Vũ Thành Đạt', 'https://images.unsplash.com/photo-1570295999919-56ceb5ecca61?auto=format&fit=crop&w=150&q=80', 4, 'Phòng sạch sẽ và tiện nghi ổn, vị trí thuận lợi. Điểm trừ nhỏ là giờ cao điểm đường hơi đông một chút, nhưng nhìn chung kỳ nghỉ rất thoải mái.', 'Cảm ơn những lời nhận xét chân thành của bạn. Sự hài lòng của quý khách là động lực lớn nhất của chúng mình. Chúc bạn luôn có những chuyến đi thật vui vẻ!', '31/08/2026'),
('rev-1030685776933399138-3', '1030685776933399138', 'Trịnh Quang Huy', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=150&q=80', 5, 'Căn phòng tuyệt vời vượt xa mong đợi của mình! Rất sạch sẽ, thơm tho và đầy đủ tiện nghi từ máy sấy, bàn là đến bếp nấu. Vị trí ngay trung tâm rất thuận tiện đi lại.', 'Cảm ơn những lời nhận xét chân thành của bạn. Sự hài lòng của quý khách là động lực lớn nhất của chúng mình. Chúc bạn luôn có những chuyến đi thật vui vẻ!', '18/08/2026'),
('rev-1030685776933399138-4', '1030685776933399138', 'Hoàng Kim Ngân', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=150&q=80', 5, 'Góc ban công ngắm cảnh rất chill, ánh sáng tự nhiên ngập tràn phòng. Đồ dùng trong phòng đều mới và cao cấp. Chắc chắn sẽ quay lại khi có dịp!', 'Cảm ơn bạn rất nhiều vì đã lựa chọn nghỉ ngơi tại căn hộ của mình! Rất vui vì bạn đã có trải nghiệm đáng nhớ và hy vọng sớm được đón tiếp bạn lần tới nhé!', '07/07/2026'),
('rev-1030685776933399138-5', '1030685776933399138', 'Đặng Thế Bảo', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=150&q=80', 5, 'Vị trí đắc địa, xung quanh có rất nhiều quán cà phê đẹp và quán ăn ngon bản địa. Khóa thông minh tự nhận phòng cực kỳ tiện lợi và an toàn.', NULL, '04/07/2026'),
('rev-1572269372565817529-1', '1572269372565817529', 'Bùi Phương Linh', 'https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=150&q=80', 4, 'Không gian đẹp, chủ nhà nhiệt tình. Căn phòng hơi cách âm chưa hoàn hảo nếu có xe cộ qua lại, bù lại view và tiện nghi rất xứng đáng với giá tiền.', NULL, '12/09/2026'),
